// MOCK for local verification only: refs, numbers, + - *, no parens.
export function parseFormula(text) {
  const toks = text.match(/\s*(\d+(\.\d+)?|[A-Za-z]+\d+|[+\-*])\s*/gy);
  if (!toks || toks.join("").replace(/\s/g, "") !== text.replace(/\s/g, "")) throw new SyntaxError("bad");
  const t = toks.map((x) => x.trim());
  if (t.length % 2 === 0) throw new SyntaxError("bad");
  const node = (i) => (/^\d/.test(t[i]) ? { n: Number(t[i]) } : { r: t[i].toUpperCase() });
  let ast = node(0);
  for (let i = 1; i < t.length; i += 2) {
    if (!"+-*".includes(t[i])) throw new SyntaxError("bad");
    ast = { op: t[i], a: ast, b: node(i + 1) };
  }
  return ast;
}
export function refsOf(ast) {
  const out = [];
  const walk = (n) => { if (n.r) { if (!out.includes(n.r)) out.push(n.r); } else if (n.op) { walk(n.a); walk(n.b); } };
  walk(ast);
  return out;
}
export function evaluate(ast, lookup) {
  if (ast.n !== undefined) return ast.n;
  if (ast.r) { const v = lookup(ast.r) ?? 0; return v; }
  const a = evaluate(ast.a, lookup), b = evaluate(ast.b, lookup);
  if (typeof a === "string" && a.startsWith("#")) return a;
  if (typeof b === "string" && b.startsWith("#")) return b;
  return ast.op === "+" ? a + b : ast.op === "-" ? a - b : a * b;
}
EOF
